INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (10,10,'["Pouvez-vous décrire les étapes que vous suivez pour élaborer un dossier de permis de construire, de la conception jusqu''au dépôt ?", "Quels logiciels de conception architecturale maîtrisez-vous, et lequel utilisez-vous le plus couramment dans votre travail quotidien ?", "Comment intégrez-vous les contraintes réglementaires du Plan d''Aménagement Urbain dans vos projets de conception ?", "Quelles missions concrètes avez-vous assurées durant vos deux années d''expérience professionnelle, et dans quel type de structure ?", "Avez-vous déjà travaillé sur un projet d''envergure publique ou d''aménagement urbain ? Si oui, quel était votre rôle précis ?", "Votre Master en Architecture et Urbanisme comprend-il un volet spécifique sur la planification territoriale ou l''habitat, et comment l''avez-vous mis en pratique ?", "Pourquoi postulez-vous à l''ADER plutôt qu''à un cabinet d''architecture privé, alors que votre profil semble plus orienté vers le secteur privé ?", "Où vous voyez-vous professionnellement dans cinq ans, et comment ce poste s''inscrit-il dans cette trajectoire ?", "Que savez-vous des missions principales de l''ADER Fès-Meknès et des projets structurants qu''elle pilote dans la région ?", "Quelle est, selon vous, la différence entre travailler sur un projet architectural dans le secteur public et dans le secteur privé, notamment en termes de contraintes et de délais ?"]','[]','{}','2026-08-27 13:27:26.166508') ON CONFLICT (id) DO NOTHING;